function renderBoard(pages,map){return '<div class="review-board">'+Object.entries(STATUS).map(([state,title])=>{const rows=pages.filter(p=>record(p.slug,map).status===state);return '<section class="board-column"><div class="board-heading"><h2><i class="status-dot status-'+state+'"></i>'+title+'</h2><b>'+rows.length+'</b></div><div class="board-cards">'+rows.map(p=>'<article class="board-card"><div>'+favoriteButton(p,record(p.slug,map))+'<span class="card-group">'+esc(groupOf(p).replace(/^SEO · /,''))+'</span></div><button class="table-title" data-open="'+esc(p.slug)+'">'+esc(label(p))+'</button><span class="card-slug">/'+esc(p.slug)+'</span>'+auditBadge(p)+'</article>').join('')+(rows.length?'':'<p class="board-empty">Aucune page dans cet état.</p>')+'</div></section>';}).join('')+'</div>';}
