async function auditPage(page,{force=false}={}){if(audits.has(page.slug)&&!force)return audits.get(page.slug);try{const a=await D.audit(page);audits.set(page.slug,a);auditErrors.delete(page.slug);if(current?.slug===page.slug)renderAudit();renderStats();return a;}catch(error){auditErrors.set(page.slug,error.message);if(current?.slug===page.slug)renderAudit();throw error;}}
