    const box=document.createElement('div');box.style.cssText='max-width:390px;text-align:center;font:12px/1.8 Inter,system-ui,sans-serif;color:#6f7e91;';const message=document.createElement('p');message.textContent='Chargement de '+side.label+'…';const retry=document.createElement('button');retry.type='button';retry.className='button small';retry.textContent='Réessayer';retry.hidden=true;retry.onclick=()=>loadPreviews();box.append(message,retry);overlay.append(box);area.style.position='relative';area.append(overlay);
