async function loadPreviews(){
  if(!current)return;cancelPreviewLoads();sourceA='';$('pageCode').value='';$('downloadHtml').disabled=true;$('openPage').href='#';$('openPage').setAttribute('aria-disabled','true');
  const operation={page:current,navigation:pageNavigation,token:++loadToken,cancelled:false,controllers:[],disposers:[],sides:[{frameId:'frameA',version:$('versionA').value,label:versionLabel($('versionA').value),rendered:false,loaded:false,error:null,slow:false}]};previewOperation=operation;
  if(compare)operation.sides.push({frameId:'frameB',version:$('versionB').value,label:versionLabel($('versionB').value),rendered:false,loaded:false,error:null,slow:false});
  $('paneB').hidden=!compare;$('versionBControl').hidden=!compare;$('compareLayout').hidden=!compare;$('previewPanes').className='preview-panes'+(compare?' compare '+$('compareLayout').value:'');$('frameLabelA').textContent=operation.sides[0].label;$('frameLabelB').textContent=compare?operation.sides[1].label:'Archive';
  if(!compare){$('frameB').removeAttribute('srcdoc');$('frameB').src='about:blank';}
  operation.sides.forEach(pendingPreview);paintPreviewStatus(operation);resizePreviews();
  await Promise.all(operation.sides.map(async side=>{
    const slowTimer=setTimeout(()=>{if(previewActive(operation)&&!side.loaded){side.slow=true;paintPreviewStatus(operation);}},4500);
    try{const html=await sourceWithDeadline(operation.page,side.version,operation);if(!previewActive(operation))return;
      if(side.frameId==='frameA'){sourceA=html;$('pageCode').value=html;$('downloadHtml').disabled=false;if(!window.VerdictDesktop){$('openPage').href=previewURL(operation.page,side.version,operation.navigation);$('openPage').removeAttribute('aria-disabled');}}
      await loadPreviewFrame(side,html,operation);
    }catch(error){if(!previewActive(operation))return;side.error=error.name==='AbortError'?'Le chargement de cette source a été interrompu. Réessayez.':error.message;failPendingPreview(side);paintPreviewStatus(operation);}
    finally{clearTimeout(slowTimer);}
  }));
}

// Resolve in-frame editorial navigation back to the corresponding app dossier.
let hostedVersionPaths=null;
const bridgedPreviewDocuments=new WeakSet();
function normalizePageNavigation(value){if(!value)return null;const search=typeof value.search==='string'?value.search:'',hash=typeof value.hash==='string'?value.hash:'';if(search.length>4096||hash.length>500||(/[\u0000-\u001f]/.test(search+hash))||(search&&!search.startsWith('?'))||(hash&&!hash.startsWith('#')))throw Error('Les paramètres de navigation de cette page sont invalides.');return search||hash?{search,hash}:null;}
function previewURL(page,versionId,navigation){const url=new URL(D.versionURL(page,versionId));if(navigation){url.search=navigation.search;url.hash=navigation.hash;}return url.href;}
function appPageRoute(page,version,navigation){let route='#page/'+encodeURIComponent(page.slug);if(version!=='current'||navigation){const query=new URLSearchParams();if(version!=='current')query.set('version',version);if(navigation?.search)query.set('query',navigation.search);if(navigation?.hash)query.set('anchor',navigation.hash);route+='?'+query.toString();}return route;}
function knownHostedVersion(url){if(!hostedVersionPaths){hostedVersionPaths=new Map();for(const page of D.pages)for(const version of page.versions){try{const known=new URL(D.versionURL(page,version.id)),key=known.origin+known.pathname,previous=hostedVersionPaths.get(key);if(!previous||previous.page.isAlias&&!page.isAlias)hostedVersionPaths.set(key,{page,version:version.id});}catch(_){}}}return hostedVersionPaths.get(url.origin+url.pathname)||null;}
async function navigateHostedVersion(target,url){try{await openPage(target.page.slug,{version:target.version,navigation:normalizePageNavigation({search:url.search,hash:url.hash})});}catch(error){toast('Navigation interrompue : '+error.message,'error');}}
function bindHostedPreviewNavigation(frame){
 if(window.VerdictDesktop||!current||frame!==$('frameA')&&frame!==$('frameB'))return;let doc;try{doc=frame.contentDocument;if(!doc?.documentElement||doc.URL==='about:blank')return;}catch(_){return;}if(bridgedPreviewDocuments.has(doc))return;bridgedPreviewDocuments.add(doc);
 doc.addEventListener('click',event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const anchor=event.target.closest?.('a[href]');if(!anchor||anchor.hasAttribute('download'))return;const target=(anchor.getAttribute('target')||'').toLowerCase();if(target&&!['_self','_parent','_top'].includes(target))return;let url;try{url=new URL(anchor.getAttribute('href'),doc.baseURI);if(!['http:','https:'].includes(url.protocol))return;const here=new URL(doc.URL);if(url.origin===here.origin&&url.pathname===here.pathname&&url.search===here.search&&url.hash)return;}catch(_){return;}const known=knownHostedVersion(url);if(!known)return;event.preventDefault();navigateHostedVersion(known,url);});
 // Only the public hub's canonical GET search is app navigation. POST, uploads,
 // download forms and already handled interactive searches keep their behavior.
 doc.addEventListener('submit',event=>{if(event.defaultPrevented)return;const form=event.target;if(form.tagName!=='FORM'||(form.getAttribute('method')||'get').toLowerCase()!=='get')return;const target=(form.getAttribute('target')||'').toLowerCase();if(target&&!['_self','_parent','_top'].includes(target))return;let url,params;try{url=new URL(form.getAttribute('action')||doc.URL,doc.baseURI);const known=knownHostedVersion(url);if(!known||known.version!=='hub')return;params=new URLSearchParams();for(const [key,value]of new FormData(form)){if(typeof value!=='string'||!['q','theme'].includes(key))return;params.append(key,value);}if(!params.has('q')&&!params.has('theme'))return;url.search=params.toString();event.preventDefault();navigateHostedVersion(known,url);}catch(_){return;}});
}
function initHostedPreviewNavigation(){if(window.VerdictDesktop)return;$('previewPanes').addEventListener('load',event=>{if(event.target.tagName==='IFRAME')bindHostedPreviewNavigation(event.target);},true);}

