async function openPage(slug,{route=true,version='current',navigation=null}={}){if(!flushNotes())return;let page,nextNavigation;try{page=D.resolvePage(slug);D.getVersion(page,version);nextNavigation=normalizePageNavigation(navigation);}catch(error){toast(error.message,'error');return;}if(!current){lastSurface=surface;if(surface==='catalog')catalogScroll=window.scrollY;else exploreScroll=window.scrollY;pageWorkshop=surface==='catalog';}current=page;pageNavigation=nextNavigation;rememberExplorePage(page);setSurface('page');$('exploreView').hidden=true;$('backCatalog').textContent=lastSurface==='explore'?'← Explorer':'← Atelier';$('catalogView').hidden=true;$('pageView').hidden=false;$('breadcrumbCurrent').textContent=label(page);$('pageTitle').textContent=label(page);$('pageGroup').textContent=groupOf(page).replace(/^SEO · /,'');$('pageSlug').textContent='/'+page.slug+(page.isAlias?' → '+page.canonicalPath:'');const all=canonical,position=all.findIndex(p=>p.slug===page.slug);$('pagePosition').textContent=position>=0?(position+1)+' / '+all.length:'Redirection';$('previousPage').disabled=position<=0;$('nextPage').disabled=position<0||position>=all.length-1;setVersions();$('versionA').value=version;renderReview();selectPanel('review');setViewport(adapted?'auto':width);$('fitPreview').checked=fit;setSidebar(false);window.scrollTo({top:0,left:0,behavior:'instant'});$('mainContent').scrollTop=0;if(route){const nextRoute=appPageRoute(page,version,pageNavigation);if(location.hash!==nextRoute)history.pushState(null,'',nextRoute);}await loadPreviews();auditPage(page).catch(()=>{});}
