async function runAuditAll(){if(batchRunning)return;const token=++auditToken,pages=canonical.slice();batchRunning=true;$('batchProgress').hidden=false;$('runAuditAll').disabled=true;$('batchBar').max=pages.length;$('batchBar').value=0;let index=0,done=0,failures=0;async function worker(){while(index<pages.length&&token===auditToken){const p=pages[index++];try{await auditPage(p,{force:true});}catch(_){failures++;}if(token!==auditToken)return;done++;$('batchBar').value=done;$('batchLabel').textContent=done+' / '+pages.length+' pages analysées';$('batchDetail').textContent=label(p);if(done%5===0&&!current)renderCatalog();await new Promise(r=>setTimeout(r,0));}}await Promise.all([worker(),worker(),worker()]);if(token===auditToken){$('batchLabel').textContent='Analyse terminée · '+done+' pages';$('batchDetail').textContent=failures?failures+' fichiers indisponibles. Les autres constats sont conservés.':'Contrôles structurels terminés. La validation humaine reste distincte.';toast('Analyse terminée : '+(done-failures)+' fichiers lus'+(failures?', '+failures+' indisponibles':'')+'.');}if(token===auditToken){batchRunning=false;$('runAuditAll').disabled=false;}renderCatalog();}
