function route(){if(location.hash.startsWith('#page/')){try{const raw=location.hash.slice(6),separator=raw.indexOf('?'),slug=decodeURIComponent(separator<0?raw:raw.slice(0,separator)),params=new URLSearchParams(separator<0?'':raw.slice(separator+1));openPage(slug,{route:false,version:params.get('version')||'current',navigation:{search:params.get('query')||'',hash:params.get('anchor')||''}}).catch(error=>{toast(error.message,'error');showExplorer({route:false});});}catch(_){showExplorer({route:false});}}else if(['#catalogue','#atelier'].includes(location.hash))showCatalog({route:false});else showExplorer({route:false});}
